import{_ as a,o as s,c as t,a5 as i}from"./chunks/framework.BwlBv862.js";const h=JSON.parse('{"title":"SDK de widgets, gateway y límites de overlays","description":"","frontmatter":{"title":"SDK de widgets, gateway y límites de overlays","docId":"developer.overlays","translationKey":"developer.overlays","locale":"es","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"99d3351859ddb3a3304133f062f68b8e3130416947fc40433dc9c6bffaf85f6a","translationRevision":"c85583e3ca5d09b8e5e036553fd83606450727d27347a785793f4c35012b1e52","order":170},"headers":[],"relativePath":"es/developer/overlays.md","filePath":"es/developer/overlays.md","lastUpdated":1794611623000}'),o={name:"es/developer/overlays.md"};function r(n,e,d,l,c,p){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="widget-sdk-gateway-and-overlay-boundaries" tabindex="-1">SDK de widgets, gateway y límites de overlays <a class="header-anchor" href="#widget-sdk-gateway-and-overlay-boundaries" aria-label="Permalink to &quot;SDK de widgets, gateway y límites de overlays {#widget-sdk-gateway-and-overlay-boundaries}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo y requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Construye un widget que comparta renderizado entre vista previa local y salida OBS. Usa las herramientas Vue instaladas y conoce los <a href="./events.html">eventos</a>. La vista previa no necesita gateway ni credenciales. La salida en vivo requiere el plugin event-gateway instalado por separado y su credencial específica para widgets.</p><h2 id="add-a-template" tabindex="-1">Añadir una plantilla <a class="header-anchor" href="#add-a-template" aria-label="Permalink to &quot;Añadir una plantilla {#add-a-template}&quot;">​</a></h2><ol><li>Crea el renderizador dentro de <code>WidgetStage</code>; dimensiona respecto al padre, no a toda la ventana.</li><li>Usa <code>defineWidget</code> de <code>src/widgets/sdk/template.ts</code>. Proporciona esquema, sobres de muestra nuevos y factoría <code>create(search, clock)</code>.</li><li>Devuelve un controlador con <code>handleEnvelope</code>, <code>clear</code> y <code>dispose</code>, además del renderizado. Emplea el reloj suministrado para mantener muestras y avanzar tiempo en pruebas.</li><li>Registra la plantilla en <code>sdk/templates.ts</code> y añade entrada independiente, compilación, ruta permitida del gateway y empaquetado. Registrarla no publica automáticamente una URL.</li><li>Usa <code>WidgetHost.vue</code> tanto en el editor como en el paquete independiente; no incrustes HTML del gateway en una vista previa local.</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> widgets</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> widgets</span></span></code></pre></div><p>Conserva tokens, valores visuales y campos editables en el esquema. Los diseños se serializan como JSON y la URL copiada incluye una instantánea validada; tras guardarla de nuevo hay que copiar otra URL a OBS.</p><h2 id="gateway-protocol" tabindex="-1">Protocolo del gateway <a class="header-anchor" href="#gateway-protocol" aria-label="Permalink to &quot;Protocolo del gateway {#gateway-protocol}&quot;">​</a></h2><p><code>src/widgets/shared/gateway-client.ts</code> controla autenticación, suscripciones, latido, reconexión y huecos. Los widgets consumen sobres canónicos, sin conectarse directamente a TikTok. <code>/ws/widgets</code> es distinto de la superficie completa para clientes externos. Analiza los mensajes mediante el módulo compartido y conserva el límite de credenciales sin pasar un token completo por la WebView principal.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado y estado <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado y estado {#expected-result-and-status}&quot;">​</a></h2><p>Las vistas previas integradas y el SDK están implementados. Existen editor Cloud y código <code>cloud-overlay</code>, pero continúan los límites de validación OBS real, ilustraciones/fuentes en vivo y aplicación desde paquetes. Changes de Overlays es un seguimiento sin integrar. Rankings sigue oculto en navegación normal aunque existan widgets de clasificación.</p><h2 id="recovery" tabindex="-1">Recuperación <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperación {#recovery}&quot;">​</a></h2><p>Ante una vista previa vacía, comprueba vida del controlador, valores del esquema y dimensiones antes de debilitar políticas de origen. En vivo, revisa salud, credencial de widget y huecos explícitos. Chromium sin interfaz no demuestra aceptación OBS. El <a href="https://github.com/nglmercer/TikTools-app/tree/remake/src/widgets/sdk" target="_blank" rel="noreferrer">SDK</a> y las pruebas de protocolo compartido son las referencias actuales.</p><h2 id="operational-details" tabindex="-1">Detalles de operación <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalles de operación {#operational-details}&quot;">​</a></h2><p>La suite unitaria usa fixtures; Chromium con gateway real necesita widgets construidos y checkout externo elegido por <code>TIKTOOLS_PLUGINS_REPO</code>. Si falta fuente se omite: informa el skip. Ejecuta <code>bun x --no-install playwright test --config src/widgets/playwright.gateway.config.ts</code> para ese límite. Después verifica OBS real, credencial widget, entrega y recuperación con LIVE; Chromium headless no acredita aceptación OBS/nativa.</p>`,15)])])}const g=a(o,[["render",r]]);export{h as __pageData,g as default};
